const X=[
 {id:'H-01',lvl:0,skill:b('Kps eta s','Kps y s'),title:b('Zilar kloruroa ur puruan','Cloruro de plata en agua pura'),q:b('AgCl-ren Kps=1,8×10⁻¹⁰ da 25 °C-an.','A 25 °C Kps(AgCl)=1,8×10⁻¹⁰.'),parts:[{q:b('s mol/L','s en mol/L'),ans:1.342e-5,abs:1e-7},{q:b('Solubilitatea g/L-tan (M=143,32)','Solubilidad en g/L (M=143,32)'),ans:0.001923,abs:0.00003}],hints:[b('AgCl-ren disoziazioan s Ag⁺-ren eta Cl⁻-ren berdina da.','Al disolverse, s coincide con [Ag⁺] y [Cl⁻].'),b('Kps=s²; g/L-rako biderkatu 143,32z.','Kps=s²; multiplica por 143,32 para obtener g/L.')],sol:[b('s=√(1,8×10⁻¹⁰)=1,342×10⁻⁵ M.','s=√(1,8×10⁻¹⁰)=1,342×10⁻⁵ M.'),b('s·143,32=1,923×10⁻³ g/L.','s·143,32=1,923×10⁻³ g/L.')],res:'1,342×10⁻⁵ M; 0,001923 g/L',check:b('Ordezkatuz Kps 1,8×10⁻¹⁰ da.','Al sustituir se recupera Kps=1,8×10⁻¹⁰.'),errs:b('Kps-ren erro karratua hartu beharrean alderantziz egitea.','Invertir la raíz cuadrada de Kps.')},
 {id:'H-02',lvl:0,skill:b('Disolbagarritasuna eta estekiometria','Solubilidad y estequiometría'),title:b('A₂B gatza','Sal A₂B'),q:b('A₂B-ren Kps=3,2×10⁻¹¹ eta masa molarra 200 g/mol da.','Kps(A₂B)=3,2×10⁻¹¹ y M=200 g/mol.'),parts:[{q:'s (M)',ans:2e-4,abs:1e-6},{q:b('g/L','g/L'),ans:0.04,abs:0.001}],hints:[b('[A]=2s eta [B]=s.','[A]=2s y [B]=s.'),b('Kps=4s³.','Kps=4s³.')],sol:[b('4s³=3,2×10⁻¹¹; s=2,00×10⁻⁴ M.','4s³=3,2×10⁻¹¹; s=2,00×10⁻⁴ M.'),b('g/L=2,00×10⁻⁴·200=0,0400.','g/L=2,00×10⁻⁴·200=0,0400.')],res:'2,00×10⁻⁴ M; 0,0400 g/L',check:b('Kps=4(2,00×10⁻⁴)³=3,2×10⁻¹¹.','Kps=4(2,00×10⁻⁴)³=3,2×10⁻¹¹.'),errs:b('Ez ahaztu [A]=2s dela; koefizientea Kps-n ere berretzailea da.','No olvides [A]=2s y que el coeficiente también es exponente en Kps.')},
 {id:'H-03',lvl:1,skill:b('g/L → mol/L','g/L → mol/L'),title:b('PbI₂ disolbagarritasuna','Solubilidad de PbI₂'),q:b('PbI₂-ren masa-disolbagarritasuna 0,440 g/L da; M(PbI₂)=461,0 g/mol.','La solubilidad másica de PbI₂ es 0,440 g/L; M(PbI₂)=461,0 g/mol.'),parts:[{q:b('Solubilitate molarra (M)','Solubilidad molar (M)'),ans:0.00095445,abs:1e-6},{q:b('Kps(PbI₂)','Kps(PbI₂)'),ans:3.47e-9,abs:5e-11}],hints:[b('g/L zatitu masa molarraz.','Divide g/L por la masa molar.'),b('PbI₂-rako Kps=s(2s)²=4s³.','Para PbI₂, Kps=s(2s)²=4s³.')],sol:[b('s=0,440/461,0=9,5445×10⁻⁴ M.','s=0,440/461,0=9,5445×10⁻⁴ M.'),b('Kps=4s³=3,47×10⁻⁹.','Kps=4s³=3,47×10⁻⁹.')],res:'s=9,54×10⁻⁴ M; Kps=3,47×10⁻⁹',check:b('I⁻ orekan 2s da, ez s.','En equilibrio [I⁻]=2s, no s.'),errs:b('G/L-tik mol/L-ra igarotzean molarraz biderkatzea.','Multiplicar por la masa molar en vez de dividir al pasar de g/L a mol/L.')},
 {id:'H-04',lvl:1,skill:b('Nahasketa, Qps eta ICE','Mezcla, Qps e ICE'),title:b('AgCl hauspeatzea','Precipitación de AgCl'),q:b('25 mL 0,010 M AgNO₃ eta 25 mL 0,020 M NaCl nahasten dira; Kps=1,8×10⁻¹⁰. Kalkulatu AgCl hauspeatutako mmol-ak.','Se mezclan 25 mL de AgNO₃ 0,010 M con 25 mL de NaCl 0,020 M; Kps=1,8×10⁻¹⁰. Calcula los mmol de AgCl precipitados.'),parts:[{q:b('AgCl hauspeatua (mmol)','AgCl precipitado (mmol)'),ans:0.25,abs:0.001},{q:b('Orekan geratzen den [Ag⁺] (M)','[Ag⁺] residual en equilibrio (M)'),ans:3.6e-8,abs:2e-9}],hints:[b('Nahastu ondoko kontzentrazioak: Ag=0,005 M, Cl=0,010 M.','Tras mezclar: [Ag]=0,005 M y [Cl]=0,010 M.'),b('Ag⁺ mugatzailea da; amaierako kloruroa ≈0,005 M.','Ag⁺ es limitante; el cloruro final ≈0,005 M.')],sol:[b('Q=5×10⁻⁵>Kps, hauspeatzen da. Hasierako Ag⁺ molak 0,25 mmol dira.','Q=5×10⁻⁵>Kps, precipita. Los moles iniciales de Ag⁺ son 0,25 mmol.'),b('[Cl⁻]eq≈0,0050 M; [Ag⁺]eq=Kps/[Cl⁻]=3,6×10⁻⁸ M.','[Cl⁻]eq≈0,0050 M; [Ag⁺]eq=Kps/[Cl⁻]=3,6×10⁻⁸ M.'),b('AgCl hauspeatua=0,250 mmol (disolbatutako hondarra arbuiagarria da).','AgCl precipitado=0,250 mmol (el residuo disuelto es despreciable).')],res:'0,250 mmol; [Ag⁺]=3,6×10⁻⁸ M',check:b('Kps baldintza berriz egiaztatu: [Ag⁺][Cl⁻]=1,8×10⁻¹⁰.','Comprueba [Ag⁺][Cl⁻]=1,8×10⁻¹⁰.'),errs:b('Nahasketa bolumen osoan diluitu gabe erabiltzea.','No diluir las concentraciones al volumen total.')},
 {id:'H-05',lvl:1,skill:b('Ioi komuna','Ion común'),title:b('AgCl kloruro-ingurunean','AgCl en medio con cloruro'),q:b('AgCl-ren Kps=1,8×10⁻¹⁰ da, eta disoluzioak Cl⁻ 0,100 M du hasieran eta AgCl solidoa soberan. Kalkulatu s.','Kps(AgCl)=1,8×10⁻¹⁰; la disolución contiene inicialmente Cl⁻ 0,100 M y hay AgCl sólido en exceso. Calcula s.'),parts:[{q:b('s mol/L','s en mol/L'),ans:1.8e-9,abs:5e-11}],hints:[b('Kps=s(0,100+s).','Kps=s(0,100+s).'),b('Hurbilketa s≪0,100 egiaztatu.','Comprueba la aproximación s≪0,100.')],sol:[b('Bigarren mailako ekuazioaren erro positiboa s=[−0,100+√(0,100²+4Kps)]/2 da.','La raíz positiva es s=[−0,100+√(0,100²+4Kps)]/2.'),b('Kps/C₀=1,8×10⁻⁹ M; x txikia da 0,100 M-ren aldean, beraz hurbilketa ona da.','Kps/C₀=1,8×10⁻⁹ M; es despreciable frente a 0,100 M, así que la aproximación es válida.')],res:'s≈1,8×10⁻⁹ M',check:b('Ur puruko √Kps=1,34×10⁻⁵ M baino askoz txikiagoa da.','Es mucho menor que √Kps=1,34×10⁻⁵ M en agua pura.'),errs:b('Ioi komunaren kontzentrazioari s gehitzea ahaztea.','Olvidar sumar s a la concentración del ion común.')},
 {id:'H-06',lvl:2,skill:b('Prezipitazio selektiboa','Precipitación selectiva'),title:b('Bi hidroxidoren atalaseak','Umbrales de dos hidróxidos'),q:b('Disoluzioan Co²⁺ eta Mn²⁺ 1,0×10⁻⁴ M dira. Kps Co(OH)₂=5,9×10⁻¹⁵; Kps Mn(OH)₂=1,9×10⁻¹³.','En la disolución [Co²⁺]=[Mn²⁺]=1,0×10⁻⁴ M. Kps Co(OH)₂=5,9×10⁻¹⁵; Kps Mn(OH)₂=1,9×10⁻¹³.'),parts:[{q:b('Co precipitatzen hasteko [OH⁻] (M)','[OH⁻] de inicio para Co (M)'),ans:7.681e-6,abs:1e-8},{q:b('Mn precipitatzen hasteko [OH⁻] (M)','[OH⁻] de inicio para Mn (M)'),ans:4.359e-5,abs:1e-7}],hints:[b('Qps= [M²⁺][OH⁻]²=Kps.','Qps=[M²⁺][OH⁻]²=Kps.'),b('Isolatu [OH⁻] erro karratuaz.','Despeja [OH⁻] con una raíz cuadrada.')],sol:[b('[OH⁻]krit(Co)=√(5,9×10⁻¹⁵ / 10⁻⁴) = 7,681×10⁻⁶ M.','[OH⁻]crit(Co)=√(5,9×10⁻¹⁵ / 10⁻⁴) = 7,681×10⁻⁶ M.'),b('[OH⁻]krit(Mn)=√(1,9×10⁻¹³ / 10⁻⁴) = 4,359×10⁻⁵ M. Co(OH)₂ hasten da lehenik.','[OH⁻]crit(Mn)=√(1,9×10⁻¹³ / 10⁻⁴) = 4,359×10⁻⁵ M. Co(OH)₂ precipita primero.')],res:b('Co(OH)₂ da lehenengo.','Primero precipita Co(OH)₂.'),check:b('Co-ren atalasea Mn-rena baino 5,68 aldiz txikiagoa da.','El umbral del Co es 5,68 veces menor que el del Mn.'),errs:b('Kps txikiagoak sal solubilitate txikiagoa esan nahi du, baina dagokion hasierako katioi-kontzentrazioarekin kalkulatu atalasea.','Aunque menor Kps suele indicar menor solubilidad, calcula el umbral con la concentración inicial de cada catión.')},
 {id:'H-07',lvl:2,skill:b('pH eta Kps','pH y Kps'),title:b('Magnesio hidroxidoaren disolbagarritasuna','Solubilidad del hidróxido de magnesio'),q:b('Kps Mg(OH)₂=5,6×10⁻¹². Kalkulatu s pH=10ean eta 1,0×10⁻³ M Mg²⁺-ren hauspeatze-hasiera pH-a.','Kps Mg(OH)₂=5,6×10⁻¹². Calcula s a pH=10 y el pH de inicio de precipitación de Mg²⁺ 1,0×10⁻³ M.'),parts:[{q:'s a pH 10 (M)',ans:5.6e-4,abs:1e-6},{q:b('Hasierako pH-a','pH de inicio'),ans:9.874,abs:0.01}],hints:[b('pH=10 bada [OH⁻]=10⁻⁴ M.','A pH=10, [OH⁻]=10⁻⁴ M.'),b('Atalasean Kps=C[OH⁻]².','En el umbral Kps=C[OH⁻]².')],sol:[b('s=Kps/[OH⁻]²=5,6×10⁻⁴ M.','s=Kps/[OH⁻]²=5,6×10⁻⁴ M.'),b('[OH⁻]krit=√(5,6×10⁻¹²/10⁻³)=7,48×10⁻⁵ M; pOH=4,126, pH=9,874.','[OH⁻]crit=√(5,6×10⁻¹²/10⁻³)=7,48×10⁻⁵ M; pOH=4,126, pH=9,874.')],res:'5,6×10⁻⁴ M; pH=9,87',check:b('pH baxuagoan OH⁻ gutxiago dago eta hidroxidoa disolbagarriagoa da.','A menor pH hay menos OH⁻ y aumenta la solubilidad.'),errs:b('pH-aren noranzkoa iraultzea.','Invertir el efecto del pH.')},
 {id:'H-08',lvl:2,skill:b('Ion común y balance de precipitado','Ioi komuna eta hauspeakin-balantzea'),title:b('NaCl gaineratu AgCl asetuari','NaCl añadido a AgCl saturado'),q:b('Litro bateko AgCl-disoluzio aseari 5,85 g NaCl gehitzen zaizkio. Kps=1,6×10⁻¹⁰; M(NaCl)=58,5.','A un litro de AgCl saturado se añaden 5,85 g de NaCl. Kps=1,6×10⁻¹⁰; M(NaCl)=58,5.'),parts:[{q:b('AgCl hauspeatua (mol)','AgCl precipitado (mol)'),ans:1.2647e-5,abs:2e-8}],hints:[b('NaCl 0,100 mol dira; hasierako AgCl s₀=√Kps.','NaCl aporta 0,100 mol; inicialmente s₀=√Kps.'),b('Azken Ag⁺=Kps/[Cl⁻]≈1,6×10⁻⁹ M.','Al final [Ag⁺]=Kps/[Cl⁻]≈1,6×10⁻⁹ M.')],sol:[b('n(Ag⁺) hasiera = 1,2649×10⁻⁵ mol; NaCl-k kloruro gehiegizkoa ematen du.','n(Ag⁺) inicial = 1,2649×10⁻⁵ mol; NaCl aporta cloruro en exceso.'),b('n(AgCl) hauspeatua ≈ 1,2649×10⁻⁵ − 1,6×10⁻⁹ = 1,2647×10⁻⁵ mol.','n(AgCl) precipitado ≈ 1,2649×10⁻⁵ − 1,6×10⁻⁹ = 1,2647×10⁻⁵ mol.')],res:'1,2647×10⁻⁵ mol',check:b('Ag⁺ da mugatzailea; ezin da hasierako Ag⁺ baino gehiago hauspeatu.','Ag⁺ limita; no puede precipitar más que la plata inicial.'),errs:b('Gatza gehitzeak bolumen aldatu gabe disoluzioaren [Cl⁻] handitzen duela ez ikustea.','No reconocer que la sal incrementa [Cl⁻] en el volumen indicado.')},
 {id:'H-09',lvl:3,skill:b('Karbonato eta azido-base oreka','Equilibrio carbonato y ácido-base'),title:b('Karbonato-espeziea pH azidoan','Especiación del carbonato en medio ácido'),q:b('pH=2,60 ([H⁺]=2,5×10⁻³ M), [HCO₃⁻]=5,0×10⁻⁷ M eta Ka₂=5,0×10⁻¹¹. Kalkulatu [CO₃²⁻].','pH=2,60 ([H⁺]=2,5×10⁻³ M), [HCO₃⁻]=5,0×10⁻⁷ M y Ka₂=5,0×10⁻¹¹. Calcula [CO₃²⁻].'),parts:[{q:'[CO₃²⁻] (M)',ans:1e-14,abs:1e-15}],hints:[b('HCO₃⁻ ⇌ H⁺+CO₃²⁻; Ka₂=[H⁺][CO₃²⁻]/[HCO₃⁻].','HCO₃⁻ ⇌ H⁺+CO₃²⁻; Ka₂=[H⁺][CO₃²⁻]/[HCO₃⁻].')],sol:[b('[CO₃²⁻]=Ka₂[HCO₃⁻]/[H⁺].','[CO₃²⁻]=Ka₂[HCO₃⁻]/[H⁺].'),b('=5,0×10⁻¹¹·5,0×10⁻⁷/(2,5×10⁻³)=1,0×10⁻¹⁴ M.','=5,0×10⁻¹¹·5,0×10⁻⁷/(2,5×10⁻³)=1,0×10⁻¹⁴ M.')],res:'1,0×10⁻¹⁴ M',check:b('pH azidoan karbonato-kontzentrazioa oso txikia da bikarbonatoarekin alderatuta.','En medio ácido, el carbonato es mucho menos abundante que el bicarbonato.'),errs:b('Ka adierazpenean [H⁺] biderkatzailetzat hartu beharrean zatitzaile gisa ez erabiltzea.','Despejar Ka olvidando dividir por [H⁺].'),rubric:b('Especies y equilibrio (30 %) · ecuación de Ka (30 %) · sustitución con unidades (25 %) · orden de magnitud razonable (15 %).','Espezieak eta oreka (% 30) · Ka ekuazioa (% 30) · unitatedun ordezkapena (% 25) · magnitude-ordena arrazoizkoa (% 15).')},
 {id:'H-10',lvl:3,skill:b('Hauspeatze zatikatua eta masa-balantzea','Precipitación fraccionada y balance'),title:b('Manganesoa erdira eta NaOH masa','Mitad de Mn y masa de NaOH'),q:b('1000 L-ko disoluzioan Co²⁺ eta Mn²⁺ 1,0×10⁻⁴ M dira. Kps Co(OH)₂=5,9×10⁻¹⁵ eta Mn(OH)₂=1,9×10⁻¹³. Mn²⁺ erdira jaisteko zenbat g NaOH gehitu? Erabili M(NaOH)=40 g/mol.','En 1000 L, [Co²⁺]=[Mn²⁺]=1,0×10⁻⁴ M. Kps Co(OH)₂=5,9×10⁻¹⁵ y Mn(OH)₂=1,9×10⁻¹³. ¿Cuántos g de NaOH para reducir Mn²⁺ a la mitad? M(NaOH)=40 g/mol.'),parts:[{q:b('NaOH gehitua (g)','NaOH añadido (g)'),ans:14.335,abs:0.05}],hints:[b('Amaieran [Mn²⁺]=5,0×10⁻⁵ M; kalkulatu OH⁻ Kps-rekin.','Al final [Mn²⁺]=5,0×10⁻⁵ M; calcula [OH⁻] con Kps.'),b('Kontatu Co(OH)₂ eta Mn(OH)₂ hauspeatutako molak eta aske dagoen OH⁻.','Cuenta Co(OH)₂ y Mn(OH)₂ precipitados, más el OH⁻ libre.')],sol:[b('[OH⁻]=√(1,9×10⁻¹³/5,0×10⁻⁵)=6,16×10⁻⁵ M. Co-ren [Co²⁺]=5,9×10⁻¹⁵/[OH⁻]²=1,55×10⁻⁶ M.','[OH⁻]=√(1,9×10⁻¹³/5,0×10⁻⁵)=6,16×10⁻⁵ M. [Co²⁺]=5,9×10⁻¹⁵/[OH⁻]²=1,55×10⁻⁶ M.'),b('1000 L-tan, hauspeatutako Co=0,09845 mol eta Mn=0,0500 mol. OH⁻-ren kontsumoa=2·(0,14845)=0,2969 mol.','En 1000 L precipitan 0,09845 mol Co y 0,0500 mol Mn. Consumo de OH⁻=2·(0,14845)=0,2969 mol.'),b('OH⁻ libre=6,16×10⁻⁵·1000=0,0616 mol. Guztira n(NaOH)=0,3585 mol; m=14,34 g (ofiziala 14,335 g).','OH⁻ libre=6,16×10⁻⁵·1000=0,0616 mol. Total n(NaOH)=0,3585 mol; m=14,34 g (oficial 14,335 g).')],res:b('14,34 g NaOH (ofiziala 14,335 g).','14,34 g NaOH (oficial 14,335 g).'),check:b('NaOH mol kopuruak hauspeatutako bi katioien 2:1 OH⁻ estekiometria eta disoluzioan geratzen den OH⁻ barne hartzen ditu.','Los moles incluyen la estequiometría de 2 OH⁻ por catión precipitado y el OH⁻ libre residual.'),errs:b('Ez ahaztu lehen hauspeatzen den Co²⁺-ak ere NaOH kontsumitzen duela.','No olvides el NaOH consumido por el Co²⁺ que precipita primero.'),rubric:b('Mn helburuko hondar-kontzentrazioa eta OH⁻ (25 %) · Co oreka eta kantitateak (25 %) · NaOH molen estekiometria (30 %) · masa eta unitateak (20 %).','[Mn²⁺] hondarra eta OH⁻ ( % 25) · Co oreka eta kantitateak (% 25) · NaOH molen estekiometria (% 30) · masa eta unitateak (% 20).')}
];

